wait_for("quiz page") { @page.body.include?(TITLE) && @page.body.include?("Add question") }
click_xpath("//a[normalize-space()='Add question']", "Add question")
wait_for("question form") { @page.at_css("#question_body") }
@page.at_css("#question_body").focus.type("Dynamic option question")
click_xpath("//button[normalize-space()='Add option']", "Add option")
wait_for("option 5 label") { @page.at_xpath("//label[normalize-space()='Option 5']") }
assert(@page.at_xpath("//label[normalize-space()='Option 5 is correct']"), "Option 5 has a visible correct label")
@page.at_css("#question_options_attributes_0_body").focus.type("First option")
@page.at_css("#question_options_attributes_4_body").focus.type("Fifth option")
click_node(@page.at_css("#question_options_attributes_4_correct"), "Option 5 correct checkbox")
submit_value("Save question")
wait_for("dynamic option saved") { @page.body.include?("Dynamic option question") && @page.body.include?("Fifth option") }
assert(!@page.body.include?("First option is correct"), "only the dynamically marked option is correct")
assert(@page.xpath("//*[contains(@class,'question-item__options')]/li[contains(@class,'is-correct')]").length == 1, "the JS-added correct option is saved as correct")
puts "ok - dynamically added option row submits correctly"

click_xpath("//a[normalize-space()='Preview']", "Preview")
wait_for("preview") { @page.body.include?("Question 1 of 1") && @page.body.include?("Fifth option") }
button = @page.at_xpath("//button[normalize-space()='Fifth option']")
assert(button, "preview renders the dynamically added option as a button")
assert(button.attribute("aria-label") == "Fifth option", "preview option has exact accessible label")
click_node(button, "Fifth option preview button")
wait_for("correct preview") { @page.body.include?("Correct!") && @page.body.include?("See score") }
puts "ok - dynamically added option previews and answers correctly"

# Clean up this quiz.
click_xpath("//a[contains(normalize-space(), '←')]", "back to quiz")
wait_for("quiz page again") { @page.body.include?(TITLE) && @page.body.include?("Settings") }
dialog_message = nil
@page.on(:dialog) { |dialog| dialog_message = dialog.message; dialog.accept }
click_xpath("//a[normalize-space()='Settings']", "Settings")
wait_for("settings") { @page.at_css("#quiz_title") }
click_xpath("//button[normalize-space()='Delete quiz'] | //input[@value='Delete quiz']", "Delete quiz")
wait_for("delete dialog") { dialog_message }
wait_for("deleted") { @page.current_url.end_with?("/moderate") && !@page.body.include?(TITLE) }
puts "ok - dynamic option test quiz deleted"
browser.quit
puts "ALL DYNAMIC OPTION CHECKS PASSED"
